#nullable enable // autogenerated

using System.Collections.Generic;
using MVZ2.GameContent.Buffs;
using MVZ2.GameContent.Buffs.Contraptions;
using MVZ2.GameContent.Damages;
using MVZ2.GameContent.Detections;
using MVZ2.GameContent.Effects;
using MVZ2.GameContent.Projectiles;
using MVZ2.GameContent.Seeds;
using MVZ2.Vanilla.Audios;
using MVZ2.Vanilla.Callbacks;
using MVZ2.Vanilla.Contraptions;
using MVZ2.Vanilla.Detections;
using MVZ2.Vanilla.Entities;
using MVZ2.Vanilla.Grids;
using MVZ2.Vanilla.Level;
using MVZ2.Vanilla.Properties;
using MVZ2Logic;
using PVZEngine;
using PVZEngine.Auras;
using PVZEngine.Buffs;
using PVZEngine.Callbacks;
using PVZEngine.Damages;
using PVZEngine.Entities;
using PVZEngine.Level;
using Tools;
using UnityEngine;

namespace MVZ2.GameContent.Contraptions
{
    [EntityBehaviourDefinition(VanillaContraptionNames.soulFurnace)]
    public class SoulFurnace : DispenserFamily
    {
        public SoulFurnace(string nsp, string name) : base(nsp, name)
        {
            evocationDetector = new SoulFurnaceEvocationDetector();
            AddAura(new SacrificeAura());
        }

        public override void Init(Entity entity)
        {
            base.Init(entity);
            InitShootTimer(entity);
            var fuel = 0;
            if (entity.Level.IsIZombie())
            {
                fuel = I_ZOMBIE_FUEL;
            }
            SetFuel(entity, fuel);
        }
        protected override void UpdateAI(Entity entity)
        {
            base.UpdateAI(entity);
            var fuel = GetFuel(entity);
            if (fuel > 0)
            {
                if (!entity.IsEvoked())
                {
                    ShootTick(entity);
                }
                else
                {
                    EvokedUpdate(entity);
                }
            }

            UpdateSacrifice(entity);
            var percentage = fuel / (float)MAX_FUEL;
            float light = 0;
            if (fuel > 0)
            {
                light = Mathf.Lerp(0.5f, 1, percentage);
            }
            var bar = GetDisplayFuel(entity);
            bar = bar * 0.5f + (percentage) * 0.5f;
            SetDisplayFuel(entity, bar);

            entity.SetAnimationFloat("Light", light);
            entity.SetAnimationFloat("Bar", bar);

            entity.SetIsFire(fuel > 0);
            entity.SetLightSource(fuel > 0);
            entity.SetLightRange(Vector3.one * (240 * light));
        }
        public override Entity? Shoot(Entity entity)
        {
            var projectile = base.Shoot(entity);
            SpendFuel(entity, 1);
            return projectile;
        }
        protected override void OnEvoke(Entity entity)
        {
            base.OnEvoke(entity);
            var fuel = GetFuel(entity);
            fuel = Mathf.Max(REFUEL_THRESOLD, fuel);
            SetFuel(entity, fuel);
            entity.SetEvoked(true);
        }
        public override void PostTakeDamage(DamageOutput damage)
        {
            base.PostTakeDamage(damage);
        }
        public override void PostDeath(Entity entity, DeathInfo deathInfo)
        {
            base.PostDeath(entity, deathInfo);
            if (deathInfo.HasEffect(VanillaDamageEffects.NO_DEATH_TRIGGER) || deathInfo.HasEffect(VanillaDamageEffects.DIG))
                return;
            var furnace = entity;
            var fuel = GetFuel(furnace);
            for (int i = 1; i <= fuel; i++)
            {
                var angle = entity.RNG.Next(-30, 31);
                var param = furnace.GetShootParams();
                param.velocity = new Vector3(Mathf.Cos(angle * Mathf.Deg2Rad), 0, Mathf.Sin(angle * Mathf.Deg2Rad)) * entity.GetFacingX() * entity.RNG.Next(15f, 18f);
                furnace.ShootProjectile(param)?.Let(e => { SoulfireBall.SetBlast(e, true); SoulfireBall.SetSplited(e, true); });
            }
        }
        protected override Detector GetDetector()
        {
            return new DispenserDetector()
            {
                canDetectInvisible = true,
                ignoreHighEnemy = true
            };
        }

        public int GetFuel(Entity entity) => entity.GetBehaviourField<int>(ID, PROP_FUEL);
        public void SetFuel(Entity entity, int value) => entity.SetBehaviourField(ID, PROP_FUEL, Mathf.Clamp(value, 0, MAX_FUEL));
        public void AddFuel(Entity entity, int value)
        {
            SetFuel(entity, GetFuel(entity) + value);
        }
        public void SpendFuel(Entity entity, int value)
        {
            var fuelBefore = GetFuel(entity);
            AddFuel(entity, -value);
            var fuelAfter = GetFuel(entity);
            if (fuelAfter <= 0 && fuelBefore > 0)
            {
                entity.PlaySound(VanillaSoundID.fizz);
                SetSacrificeInteraction(entity, SACRIFICE_INTERACTION_FIRE);
            }
        }
        public float GetDisplayFuel(Entity entity) => entity.GetBehaviourField<float>(ID, PROP_DISPLAY_FUEL);
        public void SetDisplayFuel(Entity entity, float value) => entity.SetBehaviourField(ID, PROP_DISPLAY_FUEL, value);
        public bool CanSacrifice(Entity entity, Entity soulFurnace)
        {
            bool canSacrifice = entity.Type == EntityTypes.PLANT && !entity.IsDead && GetFuel(soulFurnace) <= REFUEL_THRESOLD;
            var result = new CallbackResult(canSacrifice);
            entity.Level.Triggers.RunCallbackWithResultFiltered(VanillaLevelCallbacks.CAN_CONTRAPTION_SACRIFICE, new VanillaLevelCallbacks.ContraptionSacrificeValueParams(entity, soulFurnace), result, entity.GetDefinitionID());
            return result.GetValue<bool>();
        }
        public static int GetSacrificeFuel(Entity entity, Entity soulFurnace)
        {
            int fuel = 10;

            var game = Global.Game;

            float fuelMultiplier = 1;

            int cost = entity.GetCost();
            var rechargeID = entity.GetRechargeID();
            if (rechargeID != null)
            {
                var rechargeDef = game.GetRechargeDefinition(rechargeID);
                if (rechargeDef != null)
                {
                    fuelMultiplier = rechargeDef.GetQuality();
                }
            }

            fuel = Mathf.CeilToInt((fuel + cost / 3f) * fuelMultiplier);
            var result = new CallbackResult(fuel);
            entity.Level.Triggers.RunCallbackWithResult(VanillaLevelCallbacks.GET_CONTRAPTION_SACRIFICE_FUEL, new VanillaLevelCallbacks.ContraptionSacrificeValueParams(entity, soulFurnace), result);
            return result.GetValue<int>();
        }
        public void Sacrifice(Entity entity, Entity soulFurnace, int fuel)
        {
            var result = new CallbackResult(true);
            Global.Game.RunCallbackWithResultFiltered(VanillaLevelCallbacks.PRE_CONTRAPTION_SACRIFICE, new VanillaLevelCallbacks.ContraptionSacrificeParams(entity, soulFurnace, fuel), result, entity.GetDefinitionID());
            if (!result.GetValue<bool>())
                return;

            var effects = new DamageEffectList(VanillaDamageEffects.SACRIFICE, VanillaDamageEffects.SELF_DAMAGE);
            entity.Die(effects, soulFurnace);
            AddFuel(soulFurnace, fuel);
            SacrificeInteractions(entity, soulFurnace);
            entity.Level.Spawn(VanillaEffectID.soulfireBurn, entity.GetCenter(), soulFurnace);
            entity.PlaySound(VanillaSoundID.refuel);

            Global.Game.RunCallbackFiltered(VanillaLevelCallbacks.POST_CONTRAPTION_SACRIFICE, new VanillaLevelCallbacks.ContraptionSacrificeParams(entity, soulFurnace, fuel), entity.GetDefinitionID());
        }
        private void UpdateSacrifice(Entity furnace)
        {
            if (furnace.IsDead)
                return;
            var column = furnace.GetColumn();
            var lane = furnace.GetLane();
            var targetGrid = furnace.Level.GetGrid(column + 1 * furnace.GetFacingX(), lane);
            if (targetGrid == null)
                return;
            var layers = targetGrid.GetLayers();
            var orderedLayers = VanillaGridLayers.sacrificeLayers;
            foreach (var layer in orderedLayers)
            {
                var ent = targetGrid.GetLayerEntity(layer);
                if (ent == null || !CanSacrifice(ent, furnace))
                    continue;
                var fuel = GetSacrificeFuel(ent, furnace);
                Sacrifice(ent, furnace, fuel);
                break;
            }
        }
        private void SacrificeInteractions(Entity entity, Entity soulFurnace)
        {
            NamespaceID? function = entity.GetFunction();
            if (function == null)
                return;
            if (function == VanillaBlueprintFunctions.bomb)
            {
                for (int i = 0; i < 30; i++)
                {
                    var direction = Quaternion.Euler(0, i * 12, 0) * Vector3.right;
                    var velocity = direction * soulFurnace.GetShotVelocity().magnitude;
                    entity.ShootProjectile(new ShootParams()
                    {
                        projectileID = soulFurnace.GetProjectileID(),
                        position = entity.GetCenter(),
                        velocity = velocity,
                        faction = soulFurnace.GetFaction(),
                        damage = soulFurnace.GetDamage()
                    });
                }
            }
            if (interactionDict.TryGetValue(function, out var type))
            {
                SwitchInteraction(soulFurnace, type);
            }
        }
        private void EvokedUpdate(Entity entity)
        {
            detectBuffer.Clear();
            evocationDetector.DetectMultiple(entity, detectBuffer);
            var shootPoint = entity.GetShootPoint();
            Vector3 shootDir;
            if (detectBuffer.Count <= 0)
            {
                shootDir = entity.GetFacingDirection();
            }
            else
            {
                var targetCollider = detectBuffer.Random(entity.RNG);
                var target = targetCollider.Entity;
                shootDir = (target.Position - shootPoint).normalized;
                shootDir.y = 0;
            }
            var shotspeed = entity.GetShotVelocity().magnitude * 2;
            var velocity = shotspeed * shootDir;
            var projectile = entity.ShootProjectile(entity.GetProjectileID(), velocity);

            if (projectile != null)
            {
                SoulfireBall.SetBlast(projectile, true);
                SoulfireBall.SetSplited(projectile, true);
                entity.PlaySound(VanillaSoundID.darkSkiesCast);
            }

            SpendFuel(entity, 1);

            if (GetFuel(entity) <= 0)
            {
                entity.SetEvoked(false);
            }
        }

        public static int GetSacrificeInteraction(Entity entity) => entity.GetBehaviourField<int>(ID, PROP_SACRIFICE_INTERACTION);
        public static void SetSacrificeInteraction(Entity entity, int value) => entity.SetBehaviourField(ID, PROP_SACRIFICE_INTERACTION, value);
        private void SwitchInteraction(Entity furnace, int interaction)
        {
            int interactionBefore = GetSacrificeInteraction(furnace);
            SetSacrificeInteraction(furnace, interaction);
            if (interaction != interactionBefore)
            {
                WhiteFlashBuff.AddToEntity(furnace, 30);
            }
        }
        public class SacrificeAura : AuraEffectDefinition
        {
            public SacrificeAura() : base(VanillaBuffID.Contraption.soulFurnaceSacrificeInteraction)
            {
            }
            public override void GetAuraTargets(AuraEffect auraEffect, List<IBuffTarget> results)
            {
                var entity = auraEffect.Source.GetEntity();
                if (entity == null)
                    return;
                if (entity.IsEvoked() || entity.IsDead || GetSacrificeInteraction(entity) == SACRIFICE_INTERACTION_FIRE)
                    return;
                results.Add(entity);
            }
            public override void UpdateTargetBuff(AuraEffect effect, IBuffTarget target, Buff buff)
            {
                base.UpdateTargetBuff(effect, target, buff);
                var entity = effect.Source.GetEntity();
                if (entity == null)
                    return;
                NamespaceID projectileID = VanillaProjectileID.soulfireBall;
                float attackSpeedMultiplier = 1f;
                float damageMultiplier = 1f;
                Vector3 shotspeedMultiplier = Vector3.one;
                switch (SoulFurnace.GetSacrificeInteraction(entity))
                {
                    case SACRIFICE_INTERACTION_PIERCE:
                        shotspeedMultiplier = Vector3.one * 1.333f;
                        projectileID = VanillaProjectileID.soulfireSaw;
                        break;
                    case SACRIFICE_INTERACTION_ICE:
                        damageMultiplier = 1.25f;
                        projectileID = VanillaProjectileID.iceBall;
                        break;
                    case SACRIFICE_INTERACTION_LIGNTNING:
                        attackSpeedMultiplier = 0.667f;
                        projectileID = VanillaProjectileID.lightningBall;
                        break;
                }
                SoulFurnaceSacrificeInteractionBuff.SetProjectileID(buff, projectileID);
                SoulFurnaceSacrificeInteractionBuff.SetAttackSpeedMultiplier(buff, attackSpeedMultiplier);
                SoulFurnaceSacrificeInteractionBuff.SetDamageMultiplier(buff, damageMultiplier);
                SoulFurnaceSacrificeInteractionBuff.SetShotVelocityMultiplier(buff, shotspeedMultiplier);
            }
        }

        private static readonly NamespaceID ID = VanillaContraptionID.soulFurnace;
        public static readonly VanillaEntityPropertyMeta<int> PROP_FUEL = new VanillaEntityPropertyMeta<int>("Fuel");
        public static readonly VanillaEntityPropertyMeta<int> PROP_SACRIFICE_INTERACTION = new VanillaEntityPropertyMeta<int>("sacrifice_interaction");
        public static readonly VanillaEntityPropertyMeta<float> PROP_DISPLAY_FUEL = new VanillaEntityPropertyMeta<float>("DisplayFuel");
        public static Dictionary<NamespaceID, int> interactionDict = new Dictionary<NamespaceID, int>()
        {
            { VanillaBlueprintFunctions.combustor, SACRIFICE_INTERACTION_FIRE },
            { VanillaBlueprintFunctions.sharpener, SACRIFICE_INTERACTION_PIERCE },
            { VanillaBlueprintFunctions.frosty, SACRIFICE_INTERACTION_ICE },
            { VanillaBlueprintFunctions.buzzer, SACRIFICE_INTERACTION_LIGNTNING },
        };
        public const int MAX_FUEL = 120;
        public const int REFUEL_THRESOLD = 20;
        public const int I_ZOMBIE_FUEL = REFUEL_THRESOLD + 5;
        #region Synergies
        public const int SACRIFICE_INTERACTION_FIRE = 0;
        public const int SACRIFICE_INTERACTION_PIERCE = 1;
        public const int SACRIFICE_INTERACTION_ICE = 2;
        public const int SACRIFICE_INTERACTION_LIGNTNING = 3;
        #endregion
        private Detector evocationDetector;
        private List<IEntityCollider> detectBuffer = new List<IEntityCollider>();
    }
}
